import { Transform } from 'class-transformer'
import {
  IsNotEmpty,
  IsOptional,
  IsString,
  Matches,
  MaxLength,
} from 'class-validator'

/** Guest session id generated by the client (web: `web-device-…`, mobile: `mobile-device-…`). */
export const DEVICE_ID_PATTERN = /^[A-Za-z0-9_-]{8,64}$/

export const AI_CHAT_TEXT_MAX_LENGTH = 2000

export class SendAiChatMessageDto {
  @Transform(({ value }: { value: unknown }) =>
    typeof value === 'string' ? value.trim() : value
  )
  @IsString()
  @IsNotEmpty()
  @MaxLength(AI_CHAT_TEXT_MAX_LENGTH)
  text!: string

  @IsOptional()
  @IsString()
  @Matches(DEVICE_ID_PATTERN, { message: 'deviceId không hợp lệ' })
  deviceId?: string

  /**
   * @deprecated Ignored. The identity of a signed-in user comes from the JWT; older clients still send
   * this field, so it is accepted (the global pipe forbids unknown fields) but never trusted.
   */
  @IsOptional()
  @IsString()
  @MaxLength(64)
  userId?: string
}
